const s = $('Normalizar solicitud + traceId').first().json;
const mem = $input.first().json || {};
let resumen = 'sin historial previo';
if (mem.resumen_consolidado) {
  try {
    const r = JSON.parse(mem.resumen_consolidado);
    resumen = [r.asunto_principal].concat(r.puntos_clave || []).filter(Boolean).join(' | ') || String(mem.resumen_consolidado);
  } catch (e) { resumen = String(mem.resumen_consolidado).slice(0, 500); }
}
const t = s.mensaje.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const motivos = [];
if (/(abogad|carta documento|defensa del consumidor|denuncia|demanda|coprec|juicio|accion legal|acciones legales)/.test(t)) motivos.push('mencion legal (Manual 6.3)');
const montos = (s.mensaje.match(/\$\s?[\d.]{4,}/g) || []).map(m => Number(m.replace(/[^\d]/g, '')));
if (montos.some(m => m > 300000)) motivos.push('monto mayor a $300.000 (Manual 6.3)');
if (/(numero de (mi )?tarjeta|codigo de seguridad|cvv|contrasena)/.test(t)) motivos.push('datos sensibles (Manual 7)');
if (/(borren mis datos|eliminen mis datos|baja de mis datos)/.test(t)) motivos.push('pedido sobre datos personales (Manual 7)');
return [{ json: { ...s,
  memoria_resumen: resumen, memoria_existe: !!mem.session_id, message_count: Number(mem.message_count || 0),
  riesgo: motivos.length ? 'ROJO' : 'VERDE', motivo_riesgo: motivos.join('; '),
  intento: 1, critica_previa: '', respuesta_previa: ''
} }];

const s = $('Acople contextual + semáforo de riesgo').first().json;
const v = $input.first().json;
let ruta = v.decision;
let motivo = '';
if (s.riesgo === 'ROJO') { ruta = 'ESCALAR'; motivo = 'RIESGO_ROJO: ' + s.motivo_riesgo; }
else if (ruta === 'ESCALAR') motivo = v.veredicto_valido ? ('UMBRAL: exactitud ' + v.veredicto.exactitud_factual + '/5 (' + v.veredicto.estado_veredicto + ')') : 'SUPERVISOR_SIN_JSON_VALIDO';
const fuentes_texto = (v.fuentes || []).map(f => f.documento + ' v' + f.version + ', seccion ' + f.seccion + ' "' + f.titulo + '", pag. ' + f.pagina).join(' | ') || (v.regla_no_se ? 'Sin cobertura documental (regla No se)' : 'Sin fuente citada');
return [{ json: {
  trace_id: s.trace_id, idempotency_key: s.idempotency_key, email_cliente: s.email_cliente, nombre: s.nombre, mensaje: s.mensaje,
  memoria_resumen: s.memoria_resumen, modo_prueba: s.modo_prueba, simular_falla: s.simular_falla,
  email_supervisor: s.email_supervisor, url_decision: s.url_decision, riesgo: s.riesgo,
  ruta, motivo, intento: v.intento, respuesta: v.respuesta, regla_no_se: v.regla_no_se, fuentes_texto,
  exactitud_factual: v.veredicto.exactitud_factual, estado_veredicto: v.veredicto.estado_veredicto,
  categoria_error: v.veredicto.categoria_error, critica: v.veredicto.critica
} }];
